import json
import requests

RESPONSES_URL = "https://ai.parspack.com/v1/responses"
API_KEY = "<API_KEY>"

# First API call with reasoning
response = requests.post(
    url=RESPONSES_URL,
    headers={
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json",
    },
    data=json.dumps({
        "model": "abrha/free-model",
        "input": "How many r's are in the word 'strawberry'?",
        "reasoning": {"effort": "medium"},
    }),
)

# Preserve context by passing the previous response id
response = response.json()

# Second API call - model continues reasoning from where it left off
response2 = requests.post(
    url=RESPONSES_URL,
    headers={
        "Authorization": f"Bearer {API_KEY}",
        "Content-Type": "application/json",
    },
    data=json.dumps({
        "model": "abrha/free-model",
        "input": "Are you sure? Think carefully.",
        "previous_response_id": response["id"],
        "reasoning": {"effort": "medium"},
    }),
)

curl https://ai.parspack.com/v1/responses \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer $API_KEY" \
  -d '{
  "model": "abrha/free-model",
  "input": "How many r's are in the word 'strawberry'?",
  "reasoning": {
    "effort": "medium"
  }
}'

import OpenAI from "openai";

const API_BASE_URL = "https://ai.parspack.com/v1";
const API_KEY = "<API_KEY>";

const client = new OpenAI({
  baseURL: API_BASE_URL,
  apiKey: API_KEY,
});

// First API call with reasoning
const response = await client.responses.create({
  model: "abrha/free-model",
  input: "How many r's are in the word 'strawberry'?",
  reasoning: { effort: "medium" },
});

// Second API call - model continues reasoning from where it left off
const response2 = await client.responses.create({
  model: "abrha/free-model",
  input: "Are you sure? Think carefully.",
  previous_response_id: response.id,
  reasoning: { effort: "medium" },
});

const RESPONSES_URL = "https://ai.parspack.com/v1/responses";
const API_KEY = "<API_KEY>";

// First API call with reasoning
let response = await fetch(RESPONSES_URL, {
  method: "POST",
  headers: {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "abrha/free-model",
    input: "How many r's are in the word 'strawberry'?",
    reasoning: { effort: "medium" },
  }),
});

// Preserve context by passing the previous response id
const result = await response.json();

// Second API call - model continues reasoning from where it left off
const response2 = await fetch(RESPONSES_URL, {
  method: "POST",
  headers: {
    Authorization: `Bearer ${API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({
    model: "abrha/free-model",
    input: "Are you sure? Think carefully.",
    previous_response_id: result.id,
    reasoning: { effort: "medium" },
  }),
});

