import fs from "node:fs/promises";

const TRANSLATIONS_URL = "https://ai.parspack.com/v1/audio/translations";
const API_KEY = "<API_KEY>";
const AUDIO_FILE_PATH = "speech.mp3";

const audioFile = await fs.openAsBlob(AUDIO_FILE_PATH);
const formData = new FormData();
formData.append("model", "openai/whisper-1");
formData.append("file", audioFile, AUDIO_FILE_PATH);

const translation = await fetch(TRANSLATIONS_URL, {
  method: "POST",
  headers: { Authorization: `Bearer ${API_KEY}` },
  body: formData,
});
console.log(await translation.json());

